INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:item.rime_axe.lore.1', 'fr', 'item.rime_axe.lore.1', '<gray>Fells trees, and hits slow but hard.', '<gray>Abat les arbres, frappe lentement mais fort.');
