INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:item.enchanted_pumpkin.name', 'fr', 'item.enchanted_pumpkin.name', 'Compressed Pumpkin', 'Citrouille compressée');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:item.enchanted_quartz.name', 'fr', 'item.enchanted_quartz.name', 'Compressed Quartz', 'Quartz compressé');
