INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:item.enchanted_raw_fish.name', 'fr', 'item.enchanted_raw_fish.name', 'Compressed Raw Fish', 'Morue crue compressée');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:item.enchanted_raw_salmon.name', 'fr', 'item.enchanted_raw_salmon.name', 'Compressed Raw Salmon', 'Saumon cru compressé');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:item.enchanted_redstone.name', 'fr', 'item.enchanted_redstone.name', 'Compressed Redstone', 'Redstone compressée');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:item.enchanted_redstone_block.name', 'fr', 'item.enchanted_redstone_block.name', 'Compacted Redstone', 'Redstone compactée');
