INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:item.enchanted_slime_ball.name', 'fr', 'item.enchanted_slime_ball.name', 'Compressed Slimeball', 'Boule de slime compressée');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:item.enchanted_slime_block.name', 'fr', 'item.enchanted_slime_block.name', 'Compacted Slime', 'Slime compacté');
