INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:item.enchanted_string.name', 'fr', 'item.enchanted_string.name', 'Compressed String', 'Ficelle compressée');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:item.enchanted_sugar.name', 'fr', 'item.enchanted_sugar.name', 'Compressed Sugar', 'Sucre compressé');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.start.name', 'fr', 'category.start.name', 'The Awakening', 'L''Éveil');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.start.desc', 'fr', 'category.start.desc', 'You wake on a drifting fragment of Aethelgard, cut from the world by the World Devourer. Learn to survive, gather pebbles and build your Fountain.', 'Tu te réveilles sur un fragment d''Aethelgard à la dérive, arraché au monde par le Dévoreur de Mondes. Apprends à survivre, ramasse des galets et bâtis ta Fontaine.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.generator.name', 'fr', 'category.generator.name', 'The First Real Generator', 'Le premier vrai générateur');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.generator.desc', 'fr', 'category.generator.desc', 'The Devourer''s stasis fields still hold your fragment. The Spring Stone and a ring of stone bricks turn your Fountain into a generator. A wrong ring never costs you anything.', 'Les champs de stase du Dévoreur retiennent encore ton fragment. La Pierre de Source et un anneau de pierre taillée transforment ta Fontaine en générateur. Un anneau raté ne te coûte jamais rien.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.variety.name', 'fr', 'category.variety.name', 'Different Generators', 'Des générateurs différents');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.variety.desc', 'fr', 'category.variety.desc', 'Dunes for sand and gravel, frost for ice and Frostium. Other survivors answer the Call: the market opens.', 'Des dunes pour le sable et le gravier, du givre pour la glace et le Frostium. D''autres survivants répondent à l''Appel : le marché ouvre.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.tiers.name', 'fr', 'category.tiers.name', 'Raise the Generators', 'Améliorer les générateurs');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.tiers.desc', 'fr', 'category.tiers.desc', 'The Forge, the cores, tiers I to IV. The crystallised memories of Aethelgard answer your hammer, and progress speeds up.', 'La Forge, les cœurs, les paliers I à IV. Les souvenirs cristallisés d''Aethelgard répondent à ton marteau, et la progression s''accélère.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.rift.name', 'fr', 'category.rift.name', 'The Hub and the Rift', 'Le Hub et la Faille');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.rift.desc', 'fr', 'category.rift.desc', 'With the Bronze armor on your back the Call shows you the way out of the islet: the Hub, its people, and the Rift where the first Echo waits.', 'Avec l''armure de bronze sur le dos, l''Appel te montre la sortie de l''îlot : le Hub, ses habitants, et la Faille où attend le premier Écho.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.nether.name', 'fr', 'category.nether.name', 'The Nether and the Ember', 'Le Nether et la Braise');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.nether.desc', 'fr', 'category.nether.desc', 'Your fragment has a slag-red twin. Through a portal wait the Ember generator, quartz and soul sand.', 'Ton fragment a un jumeau rouge scorie. Derrière un portail t''attendent le générateur de braise, le quartz et le sable des âmes.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.end.name', 'fr', 'category.end.name', 'The End and the Void', 'L''End et le Vide');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.end.desc', 'fr', 'category.end.desc', 'The Void Lens opens /island end. The Echo of the Rift haunts the Void.', 'La Lentille du Vide ouvre /island end. L''Écho de la Faille hante le Vide.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.farm.name', 'fr', 'category.farm.name', 'Farming and Food', 'Culture et nourriture');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.farm.desc', 'fr', 'category.farm.desc', 'Quiet work for a fragment that is learning to grow things again. Play it alongside the generators.', 'Un travail tranquille pour un fragment qui réapprend à faire pousser des choses. À mener en parallèle des générateurs.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.forging.name', 'fr', 'category.forging.name', 'Forge and Gear', 'Forge et équipement');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.forging.desc', 'fr', 'category.forging.desc', 'Everything the Forge makes, from the bronze tools to the Bastion keys.', 'Tout ce que fabrique la Forge, des outils de bronze aux clés du Bastion.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.machines.name', 'fr', 'category.machines.name', 'Machines and Energy', 'Machines et énergie');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.machines.desc', 'fr', 'category.machines.desc', 'Coal, cables on redstone, batteries, solar panels, then Miners that break the generator for you.', 'Charbon, câbles de redstone, batteries, panneaux solaires, puis des foreuses qui cassent le générateur à ta place.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.market.name', 'fr', 'category.market.name', 'Market and Economy', 'Marché et économie');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.market.desc', 'fr', 'category.market.desc', 'Sell, buy and auction. The market never sells or buys the rarest things.', 'Vends, achète et mets aux enchères. Le marché ne vend ni n''achète jamais les objets les plus rares.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.dungeons.name', 'fr', 'category.dungeons.name', 'Dungeons', 'Donjons');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.dungeons.desc', 'fr', 'category.dungeons.desc', 'Rooms and secrets below the Hub. Floors 6 and 7 hold the Wing Cores.', 'Salles et secrets sous le Hub. Les étages 6 et 7 renferment les Cœurs d''ailes.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.bosses.name', 'fr', 'category.bosses.name', 'The Bosses', 'Les boss');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.bosses.desc', 'fr', 'category.bosses.desc', 'The Guardians keep the Devourer''s laws in order, and the Echo of the Rift is its torn-off hunger. Each has its own silhouette and its glowing weak spot.', 'Les Gardiens font respecter les lois du Dévoreur, et l''Écho de la Faille est sa faim arrachée. Chacun a sa silhouette et son point faible lumineux.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.mastery.name', 'fr', 'category.mastery.name', 'Mastery', 'Maîtrise');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.mastery.desc', 'fr', 'category.mastery.desc', 'Long goals for survivors who have done it all.', 'De longs objectifs pour les survivants qui ont tout fait.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.challenges.name', 'fr', 'category.challenges.name', 'Challenges', 'Défis');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.challenges.desc', 'fr', 'category.challenges.desc', 'Long days of plain work: bigger numbers, once each.', 'De longues journées de labeur : de plus gros chiffres, une seule fois chacun.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.grove.name', 'fr', 'category.grove.name', 'The Whispering Grove', 'Le Bosquet murmurant');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.grove.desc', 'fr', 'category.grove.desc', 'Realm 2. Roots as wide as towers, spores that glow, islands that live. The Mycelial Queen keeps the living codes of the old world.', 'Royaume 2. Des racines larges comme des tours, des spores qui brillent, des îles vivantes. La Reine mycélienne garde les codes vivants de l''ancien monde.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.heights.name', 'fr', 'category.heights.name', 'The Frozen Heights', 'Les Cimes gelées');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.heights.desc', 'fr', 'category.heights.desc', 'Realm 3. Cities stopped in the ice, a cold that is the absence of motion, a sky that is almost within reach. The Boreal Watcher holds the world still.', 'Royaume 3. Des cités figées dans la glace, un froid qui est l''absence de mouvement, un ciel presque à portée de main. Le Guetteur boréal maintient le monde immobile.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.marsh.name', 'fr', 'category.marsh.name', 'The Putrid Marshes', 'Les Marais putrides');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.marsh.desc', 'fr', 'category.marsh.desc', 'Realm 5. Everything the Devourer threw away ends up here, and the Marsh keeps it. The Mire Abomination digests what the world discards.', 'Royaume 5. Tout ce que le Dévoreur a jeté finit ici, et le Marais le garde. L''Abomination des fanges digère ce que le monde rejette.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.citadel.name', 'fr', 'category.citadel.name', 'The Citadel of Golden Sands', 'La Citadelle des Sables d''or');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:category.citadel.desc', 'fr', 'category.citadel.desc', 'Realm 4. Rivers of gold dust that flow upward, an hourglass the size of a tower. The Temporal Pharaoh counts the hours the Devourer stole.', 'Royaume 4. Des rivières de poussière d''or qui coulent vers le haut, un sablier grand comme une tour. Le Pharaon temporel compte les heures que le Dévoreur a volées.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q001.name', 'fr', 'quest.q001.name', 'First Tree', 'Premier arbre');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q001.desc', 'fr', 'quest.q001.desc', 'Your fragment is quiet, but a lone tree still stands. Its wood is the first thing the world gives back. Break 8 logs.', 'Ton fragment est silencieux, mais un arbre solitaire se dresse encore. Son bois est la première chose que le monde te rend. Casse 8 bûches.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q002.name', 'fr', 'quest.q002.name', 'Planks', 'Planches');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q002.desc', 'fr', 'quest.q002.desc', 'Craft 4 planks.', 'Fabrique 4 planches.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q003.name', 'fr', 'quest.q003.name', 'Workbench', 'Établi');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q003.desc', 'fr', 'quest.q003.desc', 'Survivors have always built before they understood. Craft a crafting table.', 'Les survivants ont toujours construit avant de comprendre. Fabrique un établi.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q004.name', 'fr', 'quest.q004.name', 'Sticks', 'Bâtons');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q004.desc', 'fr', 'quest.q004.desc', 'Craft 4 sticks.', 'Fabrique 4 bâtons.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q005.name', 'fr', 'quest.q005.name', 'Wooden Pickaxe', 'Pioche en bois');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q005.desc', 'fr', 'quest.q005.desc', 'Craft a wooden pickaxe.', 'Fabrique une pioche en bois.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q006.name', 'fr', 'quest.q006.name', 'Pebbles', 'Galets');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q006.desc', 'fr', 'quest.q006.desc', 'The stone of Aethelgard is scarce here: the Devourer left only dust and pebbles. Right-click the ground of your island with an empty hand to pick up 9 Stone Pebbles.', 'La pierre d''Aethelgard se fait rare ici : le Dévoreur n''a laissé que de la poussière et des galets. Fais un clic droit sur le sol de ton île, la main vide, pour ramasser 9 galets de pierre.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q007.name', 'fr', 'quest.q007.name', 'First Cobblestone', 'Premières pierres');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q007.desc', 'fr', 'quest.q007.desc', 'Craft a cobblestone from 9 pebbles.', 'Fabrique des pierres à partir de 9 galets.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q008.name', 'fr', 'quest.q008.name', 'Stone Pickaxe', 'Pioche en pierre');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q008.desc', 'fr', 'quest.q008.desc', 'Craft a stone pickaxe.', 'Fabrique une pioche en pierre.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q009.name', 'fr', 'quest.q009.name', 'Wooden Sword', 'Épée en bois');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q009.desc', 'fr', 'quest.q009.desc', 'Craft a wooden sword.', 'Fabrique une épée en bois.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q010.name', 'fr', 'quest.q010.name', 'Plant a Sapling', 'Plante une pousse');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q010.desc', 'fr', 'quest.q010.desc', 'Plant a sapling.', 'Plante une pousse.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q011.name', 'fr', 'quest.q011.name', 'First Harvest', 'Première récolte');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q011.desc', 'fr', 'quest.q011.desc', 'Break 8 fully grown crops.', 'Casse 8 cultures arrivées à maturité.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q012.name', 'fr', 'quest.q012.name', 'Bread', 'Pain');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q012.desc', 'fr', 'quest.q012.desc', 'Craft bread.', 'Fabrique du pain.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q013.name', 'fr', 'quest.q013.name', 'The Fountain', 'La Fontaine');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q013.desc', 'fr', 'quest.q013.desc', 'An old memory stirs in the rock: the Call. You remember how to shape a Fountain. Craft a Fountain from 4 cobblestone and 4 logs.', 'Un vieux souvenir s''agite dans la roche : l''Appel. Tu te rappelles comment façonner une Fontaine. Fabrique une Fontaine avec 4 pierres et 4 bûches.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q014.name', 'fr', 'quest.q014.name', 'Place the Fountain', 'Pose la Fontaine');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q014.desc', 'fr', 'quest.q014.desc', 'Place your Fountain on your island. It makes a cobblestone above itself every 2 seconds.', 'Pose ta Fontaine sur ton île. Elle fait apparaître une pierre au-dessus d''elle toutes les 2 secondes.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q015.name', 'fr', 'quest.q015.name', 'Fountain Cobble', 'Pierres de Fontaine');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q015.desc', 'fr', 'quest.q015.desc', 'Break 64 cobblestone.', 'Casse 64 pierres.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q016.name', 'fr', 'quest.q016.name', 'Fountain Cobble II', 'Pierres de Fontaine II');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q016.desc', 'fr', 'quest.q016.desc', 'Break 128 more cobblestone.', 'Casse encore 128 pierres.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q017.name', 'fr', 'quest.q017.name', 'Read the Plan', 'Lis le plan');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q017.desc', 'fr', 'quest.q017.desc', 'Read the generator plan with /guide.', 'Lis le plan du générateur avec /guide.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q018.name', 'fr', 'quest.q018.name', 'Spring Stone', 'Pierre de Source');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q018.desc', 'fr', 'quest.q018.desc', 'Place the Spring Stone on the south side of your Fountain''s ring.', 'Pose la Pierre de Source sur le côté sud de l''anneau de ta Fontaine.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q019.name', 'fr', 'quest.q019.name', 'Stone Bricks', 'Pierres taillées');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q019.desc', 'fr', 'quest.q019.desc', 'Get 16 stone bricks: craft them from stone, or use a stonecutter.', 'Obtiens 16 pierres taillées : fabrique-les à partir de roche, ou utilise un tailleur de pierre.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q020.name', 'fr', 'quest.q020.name', 'The Ring', 'L''anneau');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q020.desc', 'fr', 'quest.q020.desc', 'Place 7 stone bricks around your Fountain (the Spring Stone takes the south side).', 'Pose 7 pierres taillées autour de ta Fontaine (la Pierre de Source prend le côté sud).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q021.name', 'fr', 'quest.q021.name', 'Stone Generator', 'Générateur de pierre');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q021.desc', 'fr', 'quest.q021.desc', 'The ring closes and the fragment breathes again. Complete the ring: your Fountain becomes a Stone generator (right-click it to check what is missing).', 'L''anneau se ferme et le fragment respire de nouveau. Termine l''anneau : ta Fontaine devient un générateur de pierre (fais un clic droit dessus pour voir ce qui manque).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q022.name', 'fr', 'quest.q022.name', 'Mine the Generator', 'Mine le générateur');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q022.desc', 'fr', 'quest.q022.desc', 'Break 64 cobblestone from it.', 'Casse-y 64 pierres.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q023.name', 'fr', 'quest.q023.name', 'Iron Nugget', 'Pépite de fer');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q023.desc', 'fr', 'quest.q023.desc', 'Find your first iron nugget in your generator.', 'Trouve ta première pépite de fer dans ton générateur.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q024.name', 'fr', 'quest.q024.name', 'Nugget Stash', 'Réserve de pépites');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q024.desc', 'fr', 'quest.q024.desc', 'Find 9 iron nuggets in your generator.', 'Trouve 9 pépites de fer dans ton générateur.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q025.name', 'fr', 'quest.q025.name', 'Iron Ingot', 'Lingot de fer');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q025.desc', 'fr', 'quest.q025.desc', 'Craft an iron ingot.', 'Fabrique un lingot de fer.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q026.name', 'fr', 'quest.q026.name', 'First Bucket', 'Premier seau');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q026.desc', 'fr', 'quest.q026.desc', 'Craft a bucket.', 'Fabrique un seau.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q027.name', 'fr', 'quest.q027.name', 'Bottomless Water', 'Eau sans fond');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q027.desc', 'fr', 'quest.q027.desc', 'Fill your bucket from the Spring Stone.', 'Remplis ton seau à la Pierre de Source.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q028.name', 'fr', 'quest.q028.name', 'Copper', 'Cuivre');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q028.desc', 'fr', 'quest.q028.desc', 'Find 16 raw copper in your generator.', 'Trouve 16 cuivres bruts dans ton générateur.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q029.name', 'fr', 'quest.q029.name', 'Coal', 'Charbon');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q029.desc', 'fr', 'quest.q029.desc', 'Find 16 coal in your generator.', 'Trouve 16 charbons dans ton générateur.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q030.name', 'fr', 'quest.q030.name', 'Gold', 'Or');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q030.desc', 'fr', 'quest.q030.desc', 'Find a gold nugget in your generator.', 'Trouve une pépite d''or dans ton générateur.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q031.name', 'fr', 'quest.q031.name', 'Bronze Age', 'Âge du bronze');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q031.desc', 'fr', 'quest.q031.desc', 'Bronzite, the first metal the Call taught the survivors. Your journey beyond the islet begins. Find your first Bronzite in your generator.', 'La Bronzite, le premier métal que l''Appel a appris aux survivants. Ton voyage au-delà de l''îlot commence. Trouve ta première Bronzite dans ton générateur.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q032.name', 'fr', 'quest.q032.name', 'Mine 250', 'Extraction : 250');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q032.desc', 'fr', 'quest.q032.desc', 'Break 250 cobblestone.', 'Casse 250 pierres.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q033.name', 'fr', 'quest.q033.name', 'Mine 500', 'Extraction : 500');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q033.desc', 'fr', 'quest.q033.desc', 'Break 500 cobblestone.', 'Casse 500 pierres.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q034.name', 'fr', 'quest.q034.name', 'Smelter', 'Fondeur');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q034.desc', 'fr', 'quest.q034.desc', 'Craft a furnace.', 'Fabrique un fourneau.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q035.name', 'fr', 'quest.q035.name', 'Storage', 'Rangement');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q035.desc', 'fr', 'quest.q035.desc', 'Craft two chests.', 'Fabrique deux coffres.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q036.name', 'fr', 'quest.q036.name', 'Iron Pickaxe', 'Pioche en fer');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q036.desc', 'fr', 'quest.q036.desc', 'Craft an iron pickaxe.', 'Fabrique une pioche en fer.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q037.name', 'fr', 'quest.q037.name', 'Visit the Market', 'Visite le marché');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q037.desc', 'fr', 'quest.q037.desc', 'Open the market with /market.', 'Ouvre le marché avec /market.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q038.name', 'fr', 'quest.q038.name', 'First Sales', 'Premières ventes');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q038.desc', 'fr', 'quest.q038.desc', 'Earn 200 coins.', 'Gagne 200 pièces.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q039.name', 'fr', 'quest.q039.name', 'Dune Plan', 'Plan des dunes');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q039.desc', 'fr', 'quest.q039.desc', 'Read the plans of the other generators with /guide.', 'Lis les plans des autres générateurs avec /guide.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q040.name', 'fr', 'quest.q040.name', 'Sandstone', 'Grès');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q040.desc', 'fr', 'quest.q040.desc', 'Craft 16 sandstone.', 'Fabrique 16 grès.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q041.name', 'fr', 'quest.q041.name', 'Dune Ring', 'Anneau des dunes');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q041.desc', 'fr', 'quest.q041.desc', 'Place 7 sandstone blocks around a second Fountain (a Spring Stone on the south side).', 'Pose 7 blocs de grès autour d''une deuxième Fontaine (une Pierre de Source sur le côté sud).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q042.name', 'fr', 'quest.q042.name', 'Dune Generator', 'Générateur des dunes');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q042.desc', 'fr', 'quest.q042.desc', 'Complete the sandstone ring: a Dune generator makes sand, gravel and red sand.', 'Termine l''anneau de grès : un générateur des dunes produit du sable, du gravier et du sable rouge.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q043.name', 'fr', 'quest.q043.name', 'Sand', 'Sable');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q043.desc', 'fr', 'quest.q043.desc', 'Break 64 sand.', 'Casse 64 blocs de sable.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q044.name', 'fr', 'quest.q044.name', 'Gravel', 'Gravier');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q044.desc', 'fr', 'quest.q044.desc', 'Break 64 gravel.', 'Casse 64 blocs de gravier.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q045.name', 'fr', 'quest.q045.name', 'Red Sand', 'Sable rouge');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q045.desc', 'fr', 'quest.q045.desc', 'Break 16 red sand.', 'Casse 16 blocs de sable rouge.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q046.name', 'fr', 'quest.q046.name', 'Glass', 'Verre');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q046.desc', 'fr', 'quest.q046.desc', 'Smelt 8 glass: put sand in a furnace and take the glass out.', 'Fais cuire 8 blocs de verre : mets du sable dans un fourneau et récupère le verre.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q047.name', 'fr', 'quest.q047.name', 'Concrete', 'Béton');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q047.desc', 'fr', 'quest.q047.desc', 'Craft 8 concrete powder.', 'Fabrique 8 bétons en poudre.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q048.name', 'fr', 'quest.q048.name', 'More Glass', 'Encore du verre');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q048.desc', 'fr', 'quest.q048.desc', 'Smelt 16 more glass (stained glass counts too).', 'Fais cuire 16 blocs de verre de plus (le verre teinté compte aussi).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q049.name', 'fr', 'quest.q049.name', 'Frost Ring', 'Anneau de givre');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q049.desc', 'fr', 'quest.q049.desc', 'Place 7 glass blocks around a third Fountain (a Spring Stone on the south side).', 'Pose 7 blocs de verre autour d''une troisième Fontaine (une Pierre de Source sur le côté sud).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q050.name', 'fr', 'quest.q050.name', 'Frost Generator', 'Générateur de givre');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q050.desc', 'fr', 'quest.q050.desc', 'Complete the glass ring: a Frost generator makes snow blocks, packed ice and Frostium.', 'Termine l''anneau de verre : un générateur de givre produit des blocs de neige, de la glace compactée et du Frostium.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q051.name', 'fr', 'quest.q051.name', 'Snow', 'Neige');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q051.desc', 'fr', 'quest.q051.desc', 'Break 32 snow blocks.', 'Casse 32 blocs de neige.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q052.name', 'fr', 'quest.q052.name', 'Ice', 'Glace');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q052.desc', 'fr', 'quest.q052.desc', 'Break 16 packed ice.', 'Casse 16 blocs de glace compactée.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q053.name', 'fr', 'quest.q053.name', 'Frostium', 'Frostium');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q053.desc', 'fr', 'quest.q053.desc', 'Find your first Frostium in the blocks of your Frost generator.', 'Trouve ton premier Frostium dans les blocs de ton générateur de givre.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q054.name', 'fr', 'quest.q054.name', 'Frostium Haul', 'Butin de Frostium');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q054.desc', 'fr', 'quest.q054.desc', 'Find 8 Frostium in the blocks of your Frost generator.', 'Trouve 8 Frostium dans les blocs de ton générateur de givre.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q055.name', 'fr', 'quest.q055.name', 'Second Spring', 'Deuxième source');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q055.desc', 'fr', 'quest.q055.desc', 'Place 2 more Spring Stones.', 'Pose 2 Pierres de Source de plus.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q056.name', 'fr', 'quest.q056.name', 'More Fountains', 'Plus de Fontaines');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q056.desc', 'fr', 'quest.q056.desc', 'Place 3 more Fountains.', 'Pose 3 Fontaines de plus.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q057.name', 'fr', 'quest.q057.name', 'The Forge', 'La Forge');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q057.desc', 'fr', 'quest.q057.desc', 'The Forge is the heart of every survivor camp: it turns raw memory into tools. Craft a Forge with a blast furnace, 4 iron ingots and 4 coal, then place it.', 'La Forge est le cœur de chaque camp de survivants : elle transforme les souvenirs bruts en outils. Fabrique une Forge avec un haut fourneau, 4 lingots de fer et 4 charbons, puis pose-la.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q058.name', 'fr', 'quest.q058.name', 'Open the Forge', 'Ouvre la Forge');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q058.desc', 'fr', 'quest.q058.desc', 'Open the Forge menu with /forge.', 'Ouvre le menu de la Forge avec /forge.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q059.name', 'fr', 'quest.q059.name', 'First Forging', 'Première forge');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q059.desc', 'fr', 'quest.q059.desc', 'Collect a Bronze Core from the Forge (/forge).', 'Récupère un Cœur de bronze à la Forge (/forge).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q060.name', 'fr', 'quest.q060.name', 'Raise the Generator', 'Améliore le générateur');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q060.desc', 'fr', 'quest.q060.desc', 'Reach generator tier II: forge a Bronze Core and right-click it on your island.', 'Atteins le palier II du générateur : forge un Cœur de bronze et utilise-le (clic droit) sur ton île.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q061.name', 'fr', 'quest.q061.name', 'Tier II Mining', 'Extraction palier II');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q061.desc', 'fr', 'quest.q061.desc', 'Break 500 more cobblestone.', 'Casse 500 pierres de plus.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q062.name', 'fr', 'quest.q062.name', 'Bronzite Hoard', 'Trésor de Bronzite');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q062.desc', 'fr', 'quest.q062.desc', 'Find 12 Bronzite in your generator.', 'Trouve 12 Bronzite dans ton générateur.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q063.name', 'fr', 'quest.q063.name', 'Diamond', 'Diamant');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q063.desc', 'fr', 'quest.q063.desc', 'Find a diamond in your generator.', 'Trouve un diamant dans ton générateur.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q064.name', 'fr', 'quest.q064.name', 'Ember Core', 'Cœur de braise');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q064.desc', 'fr', 'quest.q064.desc', 'Collect an Ember Core from the Forge (/forge).', 'Récupère un Cœur de braise à la Forge (/forge).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q065.name', 'fr', 'quest.q065.name', 'Tier III', 'Palier III');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q065.desc', 'fr', 'quest.q065.desc', 'Reach generator tier III: forge an Ember Core and right-click it on your island.', 'Atteins le palier III du générateur : forge un Cœur de braise et utilise-le (clic droit) sur ton île.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q066.name', 'fr', 'quest.q066.name', 'Ancient Debris', 'Débris antiques');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q066.desc', 'fr', 'quest.q066.desc', 'Find ancient debris in your generator.', 'Trouve des débris antiques dans ton générateur.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q067.name', 'fr', 'quest.q067.name', 'Mine 2,000', 'Extraction : 2 000');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q067.desc', 'fr', 'quest.q067.desc', 'Break 2,000 cobblestone.', 'Casse 2 000 pierres.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q068.name', 'fr', 'quest.q068.name', 'Void Lens', 'Lentille du Vide');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q068.desc', 'fr', 'quest.q068.desc', 'Collect a Void Lens from the Forge (/forge).', 'Récupère une Lentille du Vide à la Forge (/forge).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q069.name', 'fr', 'quest.q069.name', 'The Void Lens', 'La Lentille du Vide');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q069.desc', 'fr', 'quest.q069.desc', 'Through the lens you glimpse the gap the Devourer tore in the sky: the Rift. Reach generator tier IV: right-click the Void Lens on your island. It also opens your End (/island end).', 'À travers la lentille, tu entrevois la brèche que le Dévoreur a déchirée dans le ciel : la Faille. Atteins le palier IV du générateur : utilise la Lentille du Vide (clic droit) sur ton île. Elle ouvre aussi ton End (/island end).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q070.name', 'fr', 'quest.q070.name', 'Voidglass', 'Voidglass');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q070.desc', 'fr', 'quest.q070.desc', 'Find a Voidglass in your generator.', 'Trouve un Voidglass dans ton générateur.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q071.name', 'fr', 'quest.q071.name', 'Starcore', 'Starcore');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q071.desc', 'fr', 'quest.q071.desc', 'Find a Starcore Shard in your generator.', 'Trouve un éclat de Starcore dans ton générateur.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q072.name', 'fr', 'quest.q072.name', 'Mine 5,000', 'Extraction : 5 000');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q072.desc', 'fr', 'quest.q072.desc', 'Break 5,000 cobblestone.', 'Casse 5 000 pierres.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.hub_gate.name', 'fr', 'quest.hub_gate.name', 'The Island Gate', 'Le Portail de l''île');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.hub_gate.desc', 'fr', 'quest.hub_gate.desc', 'Bronze on your back, you feel the fragment loosen. Beyond the gate there are other survivors. Travel to the Hub with /hub (and use /island to come back).', 'Le bronze sur le dos, tu sens le fragment se desserrer. Au-delà du Portail, il y a d''autres survivants. Rends-toi au Hub avec /hub (et utilise /island pour revenir).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.hub_guard.name', 'fr', 'quest.hub_guard.name', 'The Guard', 'Le Garde');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.hub_guard.desc', 'fr', 'quest.hub_guard.desc', 'Click the Guard on the Hub plaza and listen.', 'Clique sur le Garde, sur la place du Hub, et écoute-le.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.hub_archivist.name', 'fr', 'quest.hub_archivist.name', 'The Archivist', 'L''Archiviste');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.hub_archivist.desc', 'fr', 'quest.hub_archivist.desc', 'The Archivist has kept a key cut from a shard that still remembers the sky. Click the Archivist on the Hub plaza: she keeps the key to the Rift.', 'L''Archiviste garde une clé taillée dans un éclat qui se souvient encore du ciel. Clique sur l''Archiviste, sur la place du Hub : elle détient la clé de la Faille.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.hub_merchant.name', 'fr', 'quest.hub_merchant.name', 'The Merchant', 'Le Marchand');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.hub_merchant.desc', 'fr', 'quest.hub_merchant.desc', 'Click the Merchant on the Hub plaza to learn how the market works.', 'Clique sur le Marchand, sur la place du Hub, pour apprendre comment fonctionne le marché.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.hub_market_lesson.name', 'fr', 'quest.hub_market_lesson.name', 'Market Lesson', 'Leçon de marché');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.hub_market_lesson.desc', 'fr', 'quest.hub_market_lesson.desc', 'Earn 300 coins.', 'Gagne 300 pièces.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.rift_enter.name', 'fr', 'quest.rift_enter.name', 'Enter the Rift', 'Entre dans la Faille');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.rift_enter.desc', 'fr', 'quest.rift_enter.desc', 'Carry your Echo Key to the Rift arch, west of the Hub plaza, and click the Rift Gatekeeper.', 'Porte ta Clé de l''Écho jusqu''à l''arche de la Faille, à l''ouest de la place du Hub, et clique sur le Portier de la Faille.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.echo_defeat.name', 'fr', 'quest.echo_defeat.name', 'Defeat the Echo of the Rift', 'Vaincs l''Écho de la Faille');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.echo_defeat.desc', 'fr', 'quest.echo_defeat.desc', 'The first Echo of the Devourer screams in the sky. End it, and the Eight Realms can be reached. Right-click the Echo Key on the Rift altar, then defeat the Echo of the Rift. It drops the Wing Core that grants your Wings and lights the road to the Quai des Huit.', 'Le premier Écho du Dévoreur hurle dans le ciel. Mets-y fin, et les Huit Royaumes te seront ouverts. Fais un clic droit avec la Clé de l''Écho sur l''autel de la Faille, puis vaincs l''Écho de la Faille. Il laisse le Cœur d''ailes qui te donne tes Ailes et éclaire la route vers le Quai des Huit.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.q073.name', 'fr', 'quest.q073.name', 'Nether Plan', 'Plan du Nether');
