INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.grove_01.name', 'fr', 'quest.grove_01.name', 'Through the Green Gate', 'Le Portail vert');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.grove_01.desc', 'fr', 'quest.grove_01.desc', 'Beyond the second Gate the air is thick with light. The Grove remembers how to grow. Light the Sky Gate of the Whispering Grove (defeat the Lava Colossus) and step through it at the Quai des Huit (/quai).', 'Au-delà du deuxième Portail, l''air est chargé de lumière. Le Bosquet se souvient comment pousser. Allume le Portail céleste du Bosquet murmurant (vaincs le Colosse de lave) et franchis-le au Quai des Huit (/quai).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.grove_02.name', 'fr', 'quest.grove_02.name', 'Mossy Footing', 'Sol moussu');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.grove_02.desc', 'fr', 'quest.grove_02.desc', 'Break 32 moss blocks.', 'Casse 32 blocs de mousse.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.grove_03.name', 'fr', 'quest.grove_03.name', 'First Grove Harvest', 'Première récolte du Bosquet');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.grove_03.desc', 'fr', 'quest.grove_03.desc', 'Break 16 fully grown crops.', 'Casse 16 cultures arrivées à maturité.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.grove_04.name', 'fr', 'quest.grove_04.name', 'Breathe the Spores', 'Respire les spores');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.grove_04.desc', 'fr', 'quest.grove_04.desc', 'Harvest grown crops in the Grove until you earn the Respiration affinity (40 harvests): the spore haze no longer touches you.', 'Récolte des cultures mûres dans le Bosquet jusqu''à obtenir l''affinité Respiration (40 récoltes) : la brume de spores ne t''atteint plus.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.grove_05.name', 'fr', 'quest.grove_05.name', 'Planting the Roots', 'Plante les racines');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.grove_05.desc', 'fr', 'quest.grove_05.desc', 'Plant 32 saplings.', 'Plante 32 pousses.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.grove_06.name', 'fr', 'quest.grove_06.name', 'Heartwood', 'Cœur de bois');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.grove_06.desc', 'fr', 'quest.grove_06.desc', 'Break 64 mangrove logs, the living wood of the Grove.', 'Casse 64 bûches de palétuvier, le bois vivant du Bosquet.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.grove_07.name', 'fr', 'quest.grove_07.name', 'Tame the Green', 'Dompte le vert');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.grove_07.desc', 'fr', 'quest.grove_07.desc', 'Craft a composter.', 'Fabrique un composteur.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.grove_08.name', 'fr', 'quest.grove_08.name', 'Let It Grow', 'Laisse pousser');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.grove_08.desc', 'fr', 'quest.grove_08.desc', 'Keep harvesting in the Grove until you earn the Growth affinity (200 harvests): bone meal grows a crop one more stage, anywhere.', 'Continue de récolter dans le Bosquet jusqu''à obtenir l''affinité Croissance (200 récoltes) : la poudre d''os fait avancer une culture d''un stade de plus, partout.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.grove_09.name', 'fr', 'quest.grove_09.name', 'Wake the Mycelial Queen', 'Réveille la Reine mycélienne');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.grove_09.desc', 'fr', 'quest.grove_09.desc', 'Defeat the Mycelial Queen, Guardian of the Grove.', 'Vaincs la Reine mycélienne, Gardienne du Bosquet.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.heights_01.name', 'fr', 'quest.heights_01.name', 'Through the Frozen Gate', 'Le Portail gelé');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.heights_01.desc', 'fr', 'quest.heights_01.desc', 'Beyond the third Gate nothing moves unless you make it. The Heights keep time in their ice. Light the Sky Gate of the Frozen Heights (defeat the Mycelial Queen) and step through it at the Quai des Huit (/quai).', 'Au-delà du troisième Portail, rien ne bouge si tu ne le fais pas bouger. Les Cimes gardent le temps dans leur glace. Allume le Portail céleste des Cimes gelées (vaincs la Reine mycélienne) et franchis-le au Quai des Huit (/quai).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.heights_02.name', 'fr', 'quest.heights_02.name', 'Cutting Ice', 'Taille de glace');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.heights_02.desc', 'fr', 'quest.heights_02.desc', 'Break 32 packed ice.', 'Casse 32 blocs de glace compactée.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.heights_03.name', 'fr', 'quest.heights_03.name', 'Blue Cut', 'Coupe bleue');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.heights_03.desc', 'fr', 'quest.heights_03.desc', 'Break 16 blue ice.', 'Casse 16 blocs de glace bleue.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.heights_04.name', 'fr', 'quest.heights_04.name', 'Warmth', 'Chaleur');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.heights_04.desc', 'fr', 'quest.heights_04.desc', 'Cut ice in the Heights until you earn the Warmth affinity (40 blocks): the cold no longer bites you.', 'Taille de la glace dans les Cimes jusqu''à obtenir l''affinité Chaleur (40 blocs) : le froid ne te mord plus.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.heights_05.name', 'fr', 'quest.heights_05.name', 'Crystal Spires', 'Flèches de cristal');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.heights_05.desc', 'fr', 'quest.heights_05.desc', 'Break 8 amethyst clusters, the crystals of the Heights.', 'Casse 8 amas d''améthyste, les cristaux des Cimes.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.heights_06.name', 'fr', 'quest.heights_06.name', 'Cold Storage', 'Chambre froide');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.heights_06.desc', 'fr', 'quest.heights_06.desc', 'Craft a blast furnace.', 'Fabrique un haut fourneau.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.heights_07.name', 'fr', 'quest.heights_07.name', 'Stray Hunt', 'Chasse aux vagabonds');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.heights_07.desc', 'fr', 'quest.heights_07.desc', 'Defeat 20 strays.', 'Vaincs 20 vagabonds.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.heights_08.name', 'fr', 'quest.heights_08.name', 'Stasis', 'Stase');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.heights_08.desc', 'fr', 'quest.heights_08.desc', 'Keep cutting ice in the Heights until you earn the Stasis affinity (200 blocks): sneak in the air to slow your fall, anywhere in the Heights.', 'Continue de tailler la glace dans les Cimes jusqu''à obtenir l''affinité Stase (200 blocs) : accroupis-toi en l''air pour ralentir ta chute, partout dans les Cimes.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.heights_09.name', 'fr', 'quest.heights_09.name', 'Wake the Boreal Watcher', 'Réveille le Guetteur boréal');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.heights_09.desc', 'fr', 'quest.heights_09.desc', 'Defeat the Boreal Watcher, Guardian of the Heights.', 'Vaincs le Guetteur boréal, Gardien des Cimes.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.marsh_01.name', 'fr', 'quest.marsh_01.name', 'Through the Brown Gate', 'Le Portail brun');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.marsh_01.desc', 'fr', 'quest.marsh_01.desc', 'The fifth Gate smells of wet earth and old meals. Nothing here is ever really gone. Light the Sky Gate of the Putrid Marshes (defeat the Mycelial Queen) and step through it at the Quai des Huit (/quai).', 'Le cinquième Portail sent la terre mouillée et les vieux repas. Ici, rien ne disparaît jamais vraiment. Allume le Portail céleste des Marais putrides (vaincs la Reine mycélienne) et franchis-le au Quai des Huit (/quai).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.marsh_02.name', 'fr', 'quest.marsh_02.name', 'Muddy Roots', 'Racines boueuses');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.marsh_02.desc', 'fr', 'quest.marsh_02.desc', 'Break 32 muddy mangrove roots, where Rot Resin oozes.', 'Casse 32 racines de palétuvier boueuses, là où suinte la Résine de pourriture.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.marsh_03.name', 'fr', 'quest.marsh_03.name', 'Feed the Vat', 'Nourris la cuve');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.marsh_03.desc', 'fr', 'quest.marsh_03.desc', 'Right-click a Rot Vat with expired items (rotten flesh, spider eyes, bones...) to salvage them.', 'Fais un clic droit sur une Cuve de pourriture avec des objets périmés (chair putréfiée, yeux d''araignée, os...) pour les récupérer.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.marsh_04.name', 'fr', 'quest.marsh_04.name', 'Filtered Air', 'Air filtré');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.marsh_04.desc', 'fr', 'quest.marsh_04.desc', 'Salvage until you earn the Filtered affinity (40 points): the miasma no longer weakens you.', 'Récupère jusqu''à obtenir l''affinité Filtré (40 points) : les miasmes ne t''affaiblissent plus.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.marsh_05.name', 'fr', 'quest.marsh_05.name', 'Slime Heaps', 'Tas de slime');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.marsh_05.desc', 'fr', 'quest.marsh_05.desc', 'Break 16 slime blocks from the Landfill and the Weeping Mangrove.', 'Casse 16 blocs de slime de la Décharge et de la Mangrove pleureuse.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.marsh_06.name', 'fr', 'quest.marsh_06.name', 'Reclaimer', 'Récupérateur');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.marsh_06.desc', 'fr', 'quest.marsh_06.desc', 'Keep salvaging until you earn the Reclaimer affinity (200 points): a Vat needs fewer items for each Rot Resin roll.', 'Continue de récupérer jusqu''à obtenir l''affinité Récupérateur (200 points) : une Cuve demande moins d''objets pour chaque tirage de Résine de pourriture.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.marsh_07.name', 'fr', 'quest.marsh_07.name', 'Digest the Digester', 'Digère le Digesteur');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.marsh_07.desc', 'fr', 'quest.marsh_07.desc', 'Defeat the Mire Abomination, Guardian of the Marshes.', 'Vaincs l''Abomination des fanges, Gardienne des Marais.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.citadel_01.name', 'fr', 'quest.citadel_01.name', 'Through the Golden Gate', 'Le Portail doré');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.citadel_01.desc', 'fr', 'quest.citadel_01.desc', 'Beyond the fourth Gate the hours do not agree with each other. The Citadel counts them all. Light the Sky Gate of the Citadel of Golden Sands (defeat the Mycelial Queen) and step through it at the Quai des Huit (/quai).', 'Au-delà du quatrième Portail, les heures ne s''accordent pas entre elles. La Citadelle les compte toutes. Allume le Portail céleste de la Citadelle des Sables d''or (vaincs la Reine mycélienne) et franchis-le au Quai des Huit (/quai).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.citadel_02.name', 'fr', 'quest.citadel_02.name', 'Dunes of the Citadel', 'Dunes de la Citadelle');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.citadel_02.desc', 'fr', 'quest.citadel_02.desc', 'Break 64 sandstone blocks.', 'Casse 64 blocs de grès.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.citadel_03.name', 'fr', 'quest.citadel_03.name', 'Time Surges', 'Le temps s''accélère');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.citadel_03.desc', 'fr', 'quest.citadel_03.desc', 'Be in the Citadel when the Time Tide surges: you move faster, and Chrono Modules run fast.', 'Sois dans la Citadelle quand la Marée du temps s''accélère : tu te déplaces plus vite, et les Modules chrono tournent plus vite.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.citadel_04.name', 'fr', 'quest.citadel_04.name', 'Time Stalls', 'Le temps se fige');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.citadel_04.desc', 'fr', 'quest.citadel_04.desc', 'Be in the Citadel when the Time Tide stalls: you move slower, and Chrono Modules bank the lost cycles.', 'Sois dans la Citadelle quand la Marée du temps se fige : tu te déplaces plus lentement, et les Modules chrono mettent de côté les cycles perdus.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.citadel_05.name', 'fr', 'quest.citadel_05.name', 'Gold of the Sands', 'L''or des sables');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.citadel_05.desc', 'fr', 'quest.citadel_05.desc', 'Collect 16 gold ingots to forge the Chrono Module and the Sandglass.', 'Rassemble 16 lingots d''or pour forger le Module chrono et le Sablier.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.citadel_06.name', 'fr', 'quest.citadel_06.name', 'Turn the Sandglass', 'Retourne le Sablier');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.citadel_06.desc', 'fr', 'quest.citadel_06.desc', 'Collect a Sandglass from the Forge (/forge).', 'Récupère un Sablier à la Forge (/forge).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.citadel_07.name', 'fr', 'quest.citadel_07.name', 'A Module That Remembers', 'Un module qui se souvient');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.citadel_07.desc', 'fr', 'quest.citadel_07.desc', 'Collect a Chrono Module from the Forge (/forge).', 'Récupère un Module chrono à la Forge (/forge).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.citadel_08.name', 'fr', 'quest.citadel_08.name', 'Wake the Temporal Pharaoh', 'Réveille le Pharaon temporel');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.citadel_08.desc', 'fr', 'quest.citadel_08.desc', 'Defeat the Temporal Pharaoh, Guardian of the Citadel.', 'Vaincs le Pharaon temporel, Gardien de la Citadelle.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.chop_logs.name', 'fr', 'quest.chop_logs.name', 'Lumberjack', 'Bûcheron');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.chop_logs.desc', 'fr', 'quest.chop_logs.desc', 'Chop 32 logs.', 'Abats 32 bûches.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.mine_stone.name', 'fr', 'quest.mine_stone.name', 'Stone Cutter', 'Tailleur de pierre');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.mine_stone.desc', 'fr', 'quest.mine_stone.desc', 'Mine 64 stone blocks.', 'Mine 64 blocs de roche.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.mine_ores.name', 'fr', 'quest.mine_ores.name', 'Prospector', 'Prospecteur');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.mine_ores.desc', 'fr', 'quest.mine_ores.desc', 'Mine 16 ores.', 'Mine 16 minerais.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.harvest_crops.name', 'fr', 'quest.harvest_crops.name', 'Green Thumb', 'Main verte');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.harvest_crops.desc', 'fr', 'quest.harvest_crops.desc', 'Harvest 48 fully grown crops.', 'Récolte 48 cultures arrivées à maturité.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.kill_zombies.name', 'fr', 'quest.kill_zombies.name', 'Zombie Hunter', 'Chasseur de zombies');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.kill_zombies.desc', 'fr', 'quest.kill_zombies.desc', 'Defeat 15 zombies.', 'Vaincs 15 zombies.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.kill_skeletons.name', 'fr', 'quest.kill_skeletons.name', 'Bone Collector', 'Collectionneur d''os');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.kill_skeletons.desc', 'fr', 'quest.kill_skeletons.desc', 'Defeat 15 skeletons.', 'Vaincs 15 squelettes.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.kill_spiders.name', 'fr', 'quest.kill_spiders.name', 'Web Cutter', 'Coupeur de toiles');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.kill_spiders.desc', 'fr', 'quest.kill_spiders.desc', 'Defeat 12 spiders.', 'Vaincs 12 araignées.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.kill_creepers.name', 'fr', 'quest.kill_creepers.name', 'Quiet Defusal', 'Désamorçage discret');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.kill_creepers.desc', 'fr', 'quest.kill_creepers.desc', 'Defeat 8 creepers.', 'Vaincs 8 creepers.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.kill_any.name', 'fr', 'quest.kill_any.name', 'Pest Control', 'Dératisation');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.kill_any.desc', 'fr', 'quest.kill_any.desc', 'Defeat 40 mobs.', 'Vaincs 40 monstres.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.go_fishing.name', 'fr', 'quest.go_fishing.name', 'Catch of the Day', 'Pêche du jour');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.go_fishing.desc', 'fr', 'quest.go_fishing.desc', 'Catch 12 fish.', 'Pêche 12 poissons.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.fish_lots.name', 'fr', 'quest.fish_lots.name', 'Deep Sea Angler', 'Pêcheur de haute mer');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.fish_lots.desc', 'fr', 'quest.fish_lots.desc', 'Catch 25 fish.', 'Pêche 25 poissons.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.earn_small.name', 'fr', 'quest.earn_small.name', 'Pocket Money', 'Argent de poche');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.earn_small.desc', 'fr', 'quest.earn_small.desc', 'Earn 2,000 coins.', 'Gagne 2 000 pièces.');
