INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.craft_planks.desc', 'fr', 'quest.craft_planks.desc', 'Craft 64 planks.', 'Fabrique 64 planches.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.craft_torches.name', 'fr', 'quest.craft_torches.name', 'Let There Be Light', 'Que la lumière soit');
