INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.enchant_item.desc', 'fr', 'quest.enchant_item.desc', 'Enchant 3 items.', 'Enchante 3 objets.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.place_saplings.name', 'fr', 'quest.place_saplings.name', 'Reforestation', 'Reboisement');
