INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.visit_islands.name', 'fr', 'quest.visit_islands.name', 'Fellow Survivors', 'Compagnons de survie');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.visit_islands.desc', 'fr', 'quest.visit_islands.desc', 'Visit islands 3 times.', 'Visite des îles 3 fois.');
