INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.bazaar_visit.name', 'fr', 'quest.bazaar_visit.name', 'Window Shopping', 'Lèche-vitrines');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.bazaar_visit.desc', 'fr', 'quest.bazaar_visit.desc', 'Open the Sky Exchange and see what the survivors trade.', 'Ouvre la Bourse céleste et regarde ce que s''échangent les survivants.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('fr:quest.boss_hunt.name', 'fr', 'quest.boss_hunt.name', 'Hold the Line', 'Tenir bon');
