INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:item.bronze_cleaver.lore.0', 'de', 'item.bronze_cleaver.lore.0', '<gray>Rend: <white>hits make the target', '<gray>Zerfetzen: <white>Treffer lassen das Ziel');
