INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:item.cinder_starcore_helmet.name', 'de', 'item.cinder_starcore_helmet.name', 'Cinder Starcore Helmet', 'Asche-Starcore-Helm');
