INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:item.cinder_starcore_helmet.lore.2', 'de', 'item.cinder_starcore_helmet.lore.2', '<gold>Full set, Ashen Mantle: <gray>fire, lava and hot floors hurt half as much.', '<gold>Komplettset, Aschemantel: <gray>Feuer, Lava und heiße Böden tun nur halb so weh.');
