INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:item.enchanted_quartz_block.name', 'de', 'item.enchanted_quartz_block.name', 'Compacted Quartz', 'Verdichteter Quarz');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:item.enchanted_raw_fish.name', 'de', 'item.enchanted_raw_fish.name', 'Compressed Raw Fish', 'Komprimierter roher Fisch');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:item.enchanted_raw_salmon.name', 'de', 'item.enchanted_raw_salmon.name', 'Compressed Raw Salmon', 'Komprimierter roher Lachs');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:item.enchanted_redstone.name', 'de', 'item.enchanted_redstone.name', 'Compressed Redstone', 'Komprimierter Redstone');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:item.enchanted_redstone_block.name', 'de', 'item.enchanted_redstone_block.name', 'Compacted Redstone', 'Verdichteter Redstone');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:item.enchanted_rotten_flesh.name', 'de', 'item.enchanted_rotten_flesh.name', 'Compressed Rotten Flesh', 'Komprimiertes verrottetes Fleisch');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:item.enchanted_slime_ball.name', 'de', 'item.enchanted_slime_ball.name', 'Compressed Slimeball', 'Komprimierter Schleimball');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:item.enchanted_slime_block.name', 'de', 'item.enchanted_slime_block.name', 'Compacted Slime', 'Verdichteter Schleim');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:item.enchanted_spruce_log.name', 'de', 'item.enchanted_spruce_log.name', 'Compressed Spruce Wood', 'Komprimierter Fichtenstamm');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:item.enchanted_string.name', 'de', 'item.enchanted_string.name', 'Compressed String', 'Komprimierter Faden');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:item.enchanted_sugar.name', 'de', 'item.enchanted_sugar.name', 'Compressed Sugar', 'Komprimierter Zucker');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.start.name', 'de', 'category.start.name', 'The Awakening', 'Das Erwachen');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.start.desc', 'de', 'category.start.desc', 'You wake on a drifting fragment of Aethelgard, cut from the world by the World Devourer. Learn to survive, gather pebbles and build your Fountain.', 'Du erwachst auf einem treibenden Fragment von Aethelgard, vom Weltenverschlinger aus der Welt gerissen. Lerne zu überleben, sammle Kiesel und baue deinen Brunnen.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.generator.name', 'de', 'category.generator.name', 'The First Real Generator', 'Der erste echte Generator');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.generator.desc', 'de', 'category.generator.desc', 'The Devourer''s stasis fields still hold your fragment. The Spring Stone and a ring of stone bricks turn your Fountain into a generator. A wrong ring never costs you anything.', 'Die Stasisfelder des Verschlingers halten dein Fragment noch fest. Der Quellstein und ein Ring aus Steinziegeln machen aus deinem Brunnen einen Generator. Ein falscher Ring kostet dich nie etwas.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.variety.name', 'de', 'category.variety.name', 'Different Generators', 'Andere Generatoren');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.variety.desc', 'de', 'category.variety.desc', 'Dunes for sand and gravel, frost for ice and Frostium. Other survivors answer the Call: the market opens.', 'Dünen für Sand und Kies, Frost für Eis und Frostium. Andere Überlebende folgen dem Ruf: Der Markt öffnet.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.tiers.name', 'de', 'category.tiers.name', 'Raise the Generators', 'Verbessere die Generatoren');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.tiers.desc', 'de', 'category.tiers.desc', 'The Forge, the cores, tiers I to IV. The crystallised memories of Aethelgard answer your hammer, and progress speeds up.', 'Die Schmiede, die Kerne, Stufe I bis IV. Die kristallisierten Erinnerungen von Aethelgard antworten auf deinen Hammer, und der Fortschritt nimmt Fahrt auf.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.rift.name', 'de', 'category.rift.name', 'The Hub and the Rift', 'Der Hub und der Riss');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.rift.desc', 'de', 'category.rift.desc', 'With the Bronze armor on your back the Call shows you the way out of the islet: the Hub, its people, and the Rift where the first Echo waits.', 'Mit der Bronzerüstung auf dem Rücken zeigt dir der Ruf den Weg aus dem Inselchen: den Hub, seine Bewohner und den Riss, wo das erste Echo wartet.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.nether.name', 'de', 'category.nether.name', 'The Nether and the Ember', 'Der Nether und die Glut');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.nether.desc', 'de', 'category.nether.desc', 'Your fragment has a slag-red twin. Through a portal wait the Ember generator, quartz and soul sand.', 'Dein Fragment hat einen schlackenroten Zwilling. Hinter einem Portal warten der Glutgenerator, Quarz und Seelensand.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.end.name', 'de', 'category.end.name', 'The End and the Void', 'Das End und die Leere');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.end.desc', 'de', 'category.end.desc', 'The Void Lens opens /island end. The Echo of the Rift haunts the Void.', 'Die Leerenlinse öffnet /island end. Das Echo des Risses sucht die Leere heim.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.farm.name', 'de', 'category.farm.name', 'Farming and Food', 'Ackerbau und Nahrung');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.farm.desc', 'de', 'category.farm.desc', 'Quiet work for a fragment that is learning to grow things again. Play it alongside the generators.', 'Ruhige Arbeit für ein Fragment, das gerade wieder lernt, etwas wachsen zu lassen. Spiel sie parallel zu den Generatoren.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.forging.name', 'de', 'category.forging.name', 'Forge and Gear', 'Schmiede und Ausrüstung');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.forging.desc', 'de', 'category.forging.desc', 'Everything the Forge makes, from the bronze tools to the Bastion keys.', 'Alles, was die Schmiede herstellt, von den Bronzewerkzeugen bis zu den Bastion-Schlüsseln.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.machines.name', 'de', 'category.machines.name', 'Machines and Energy', 'Maschinen und Energie');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.machines.desc', 'de', 'category.machines.desc', 'Coal, cables on redstone, batteries, solar panels, then Miners that break the generator for you.', 'Kohle, Kabel auf Redstone, Batterien, Solarmodule und dann Bohrer, die den Generator für dich abbauen.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.market.name', 'de', 'category.market.name', 'Market and Economy', 'Markt und Wirtschaft');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.market.desc', 'de', 'category.market.desc', 'Sell, buy and auction. The market never sells or buys the rarest things.', 'Verkaufe, kaufe und versteigere. Der Markt verkauft und kauft die seltensten Dinge nie.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.dungeons.name', 'de', 'category.dungeons.name', 'Dungeons', 'Dungeons');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.dungeons.desc', 'de', 'category.dungeons.desc', 'Rooms and secrets below the Hub. Floors 6 and 7 hold the Wing Cores.', 'Räume und Geheimnisse unter dem Hub. Auf den Etagen 6 und 7 liegen die Flügelkerne.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.bosses.name', 'de', 'category.bosses.name', 'The Bosses', 'Die Bosse');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.bosses.desc', 'de', 'category.bosses.desc', 'The Guardians keep the Devourer''s laws in order, and the Echo of the Rift is its torn-off hunger. Each has its own silhouette and its glowing weak spot.', 'Die Wächter halten die Gesetze des Verschlingers aufrecht, und das Echo des Risses ist sein abgerissener Hunger. Jeder hat seine eigene Silhouette und seine leuchtende Schwachstelle.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.mastery.name', 'de', 'category.mastery.name', 'Mastery', 'Meisterschaft');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.mastery.desc', 'de', 'category.mastery.desc', 'Long goals for survivors who have done it all.', 'Langfristige Ziele für Überlebende, die schon alles geschafft haben.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.challenges.name', 'de', 'category.challenges.name', 'Challenges', 'Herausforderungen');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.challenges.desc', 'de', 'category.challenges.desc', 'Long days of plain work: bigger numbers, once each.', 'Lange Tage einfacher Arbeit: größere Zahlen, jeweils einmal.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.grove.name', 'de', 'category.grove.name', 'The Whispering Grove', 'Der Flüsternde Hain');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.grove.desc', 'de', 'category.grove.desc', 'Realm 2. Roots as wide as towers, spores that glow, islands that live. The Mycelial Queen keeps the living codes of the old world.', 'Reich 2. Wurzeln so breit wie Türme, leuchtende Sporen, lebendige Inseln. Die Myzelkönigin hütet die lebenden Codes der alten Welt.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.heights.name', 'de', 'category.heights.name', 'The Frozen Heights', 'Die Gefrorenen Höhen');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.heights.desc', 'de', 'category.heights.desc', 'Realm 3. Cities stopped in the ice, a cold that is the absence of motion, a sky that is almost within reach. The Boreal Watcher holds the world still.', 'Reich 3. Im Eis erstarrte Städte, eine Kälte, die der Stillstand jeder Bewegung ist, ein Himmel fast in Reichweite. Der Boreal-Wächter hält die Welt still.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.marsh.name', 'de', 'category.marsh.name', 'The Putrid Marshes', 'Die Fauligen Sümpfe');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.marsh.desc', 'de', 'category.marsh.desc', 'Realm 5. Everything the Devourer threw away ends up here, and the Marsh keeps it. The Mire Abomination digests what the world discards.', 'Reich 5. Alles, was der Verschlinger weggeworfen hat, landet hier, und der Sumpf behält es. Das Sumpfscheusal verdaut, was die Welt verwirft.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.citadel.name', 'de', 'category.citadel.name', 'The Citadel of Golden Sands', 'Die Zitadelle der Goldenen Sande');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:category.citadel.desc', 'de', 'category.citadel.desc', 'Realm 4. Rivers of gold dust that flow upward, an hourglass the size of a tower. The Temporal Pharaoh counts the hours the Devourer stole.', 'Reich 4. Flüsse aus Goldstaub, die aufwärts fließen, eine Sanduhr so groß wie ein Turm. Der Zeitpharao zählt die Stunden, die der Verschlinger gestohlen hat.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q001.name', 'de', 'quest.q001.name', 'First Tree', 'Der erste Baum');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q001.desc', 'de', 'quest.q001.desc', 'Your fragment is quiet, but a lone tree still stands. Its wood is the first thing the world gives back. Break 8 logs.', 'Dein Fragment ist still, doch ein einsamer Baum steht noch. Sein Holz ist das Erste, was die Welt dir zurückgibt. Baue 8 Stämme ab.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q002.name', 'de', 'quest.q002.name', 'Planks', 'Bretter');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q002.desc', 'de', 'quest.q002.desc', 'Craft 4 planks.', 'Stelle 4 Bretter her.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q003.name', 'de', 'quest.q003.name', 'Workbench', 'Werkbank');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q003.desc', 'de', 'quest.q003.desc', 'Survivors have always built before they understood. Craft a crafting table.', 'Überlebende haben schon immer gebaut, bevor sie verstanden. Stelle eine Werkbank her.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q004.name', 'de', 'quest.q004.name', 'Sticks', 'Stöcke');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q004.desc', 'de', 'quest.q004.desc', 'Craft 4 sticks.', 'Stelle 4 Stöcke her.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q005.name', 'de', 'quest.q005.name', 'Wooden Pickaxe', 'Holzspitzhacke');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q005.desc', 'de', 'quest.q005.desc', 'Craft a wooden pickaxe.', 'Stelle eine Holzspitzhacke her.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q006.name', 'de', 'quest.q006.name', 'Pebbles', 'Kiesel');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q006.desc', 'de', 'quest.q006.desc', 'The stone of Aethelgard is scarce here: the Devourer left only dust and pebbles. Right-click the ground of your island with an empty hand to pick up 9 Stone Pebbles.', 'Der Stein von Aethelgard ist hier knapp: Der Verschlinger hat nur Staub und Kiesel übrig gelassen. Mach mit leerer Hand einen Rechtsklick auf den Boden deiner Insel, um 9 Steinkiesel aufzuheben.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q007.name', 'de', 'quest.q007.name', 'First Cobblestone', 'Erster Bruchstein');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q007.desc', 'de', 'quest.q007.desc', 'Craft a cobblestone from 9 pebbles.', 'Stelle einen Bruchstein aus 9 Kieseln her.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q008.name', 'de', 'quest.q008.name', 'Stone Pickaxe', 'Steinspitzhacke');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q008.desc', 'de', 'quest.q008.desc', 'Craft a stone pickaxe.', 'Stelle eine Steinspitzhacke her.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q009.name', 'de', 'quest.q009.name', 'Wooden Sword', 'Holzschwert');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q009.desc', 'de', 'quest.q009.desc', 'Craft a wooden sword.', 'Stelle ein Holzschwert her.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q010.name', 'de', 'quest.q010.name', 'Plant a Sapling', 'Setzling pflanzen');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q010.desc', 'de', 'quest.q010.desc', 'Plant a sapling.', 'Pflanze einen Setzling.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q011.name', 'de', 'quest.q011.name', 'First Harvest', 'Erste Ernte');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q011.desc', 'de', 'quest.q011.desc', 'Break 8 fully grown crops.', 'Baue 8 ausgewachsene Feldfrüchte ab.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q012.name', 'de', 'quest.q012.name', 'Bread', 'Brot');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q012.desc', 'de', 'quest.q012.desc', 'Craft bread.', 'Stelle Brot her.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q013.name', 'de', 'quest.q013.name', 'The Fountain', 'Der Brunnen');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q013.desc', 'de', 'quest.q013.desc', 'An old memory stirs in the rock: the Call. You remember how to shape a Fountain. Craft a Fountain from 4 cobblestone and 4 logs.', 'Eine alte Erinnerung regt sich im Fels: der Ruf. Du weißt wieder, wie man einen Brunnen formt. Stelle einen Brunnen aus 4 Bruchsteinen und 4 Stämmen her.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q014.name', 'de', 'quest.q014.name', 'Place the Fountain', 'Brunnen aufstellen');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q014.desc', 'de', 'quest.q014.desc', 'Place your Fountain on your island. It makes a cobblestone above itself every 2 seconds.', 'Platziere deinen Brunnen auf deiner Insel. Er erzeugt alle 2 Sekunden einen Bruchstein über sich.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q015.name', 'de', 'quest.q015.name', 'Fountain Cobble', 'Brunnen-Bruchstein');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q015.desc', 'de', 'quest.q015.desc', 'Break 64 cobblestone.', 'Baue 64 Bruchstein ab.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q016.name', 'de', 'quest.q016.name', 'Fountain Cobble II', 'Brunnen-Bruchstein II');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q016.desc', 'de', 'quest.q016.desc', 'Break 128 more cobblestone.', 'Baue 128 weitere Bruchsteine ab.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q017.name', 'de', 'quest.q017.name', 'Read the Plan', 'Den Plan lesen');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q017.desc', 'de', 'quest.q017.desc', 'Read the generator plan with /guide.', 'Lies den Generatorplan mit /guide.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q018.name', 'de', 'quest.q018.name', 'Spring Stone', 'Quellstein');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q018.desc', 'de', 'quest.q018.desc', 'Place the Spring Stone on the south side of your Fountain''s ring.', 'Platziere den Quellstein auf der Südseite des Rings um deinen Brunnen.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q019.name', 'de', 'quest.q019.name', 'Stone Bricks', 'Steinziegel');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q019.desc', 'de', 'quest.q019.desc', 'Get 16 stone bricks: craft them from stone, or use a stonecutter.', 'Besorge 16 Steinziegel: Stelle sie aus Stein her oder nutze eine Steinsäge.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q020.name', 'de', 'quest.q020.name', 'The Ring', 'Der Ring');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q020.desc', 'de', 'quest.q020.desc', 'Place 7 stone bricks around your Fountain (the Spring Stone takes the south side).', 'Platziere 7 Steinziegel rund um deinen Brunnen (der Quellstein nimmt die Südseite ein).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q021.name', 'de', 'quest.q021.name', 'Stone Generator', 'Steingenerator');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q021.desc', 'de', 'quest.q021.desc', 'The ring closes and the fragment breathes again. Complete the ring: your Fountain becomes a Stone generator (right-click it to check what is missing).', 'Der Ring schließt sich und das Fragment atmet wieder. Vervollständige den Ring: Dein Brunnen wird zum Steingenerator (Rechtsklick darauf zeigt, was noch fehlt).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q022.name', 'de', 'quest.q022.name', 'Mine the Generator', 'Den Generator abbauen');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q022.desc', 'de', 'quest.q022.desc', 'Break 64 cobblestone from it.', 'Baue 64 Bruchstein daraus ab.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q023.name', 'de', 'quest.q023.name', 'Iron Nugget', 'Eisenklumpen');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q023.desc', 'de', 'quest.q023.desc', 'Find your first iron nugget in your generator.', 'Finde deinen ersten Eisenklumpen in deinem Generator.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q024.name', 'de', 'quest.q024.name', 'Nugget Stash', 'Klumpenvorrat');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q024.desc', 'de', 'quest.q024.desc', 'Find 9 iron nuggets in your generator.', 'Finde 9 Eisenklumpen in deinem Generator.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q025.name', 'de', 'quest.q025.name', 'Iron Ingot', 'Eisenbarren');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q025.desc', 'de', 'quest.q025.desc', 'Craft an iron ingot.', 'Stelle einen Eisenbarren her.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q026.name', 'de', 'quest.q026.name', 'First Bucket', 'Erster Eimer');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q026.desc', 'de', 'quest.q026.desc', 'Craft a bucket.', 'Stelle einen Eimer her.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q027.name', 'de', 'quest.q027.name', 'Bottomless Water', 'Endloses Wasser');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q027.desc', 'de', 'quest.q027.desc', 'Fill your bucket from the Spring Stone.', 'Fülle deinen Eimer am Quellstein.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q028.name', 'de', 'quest.q028.name', 'Copper', 'Kupfer');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q028.desc', 'de', 'quest.q028.desc', 'Find 16 raw copper in your generator.', 'Finde 16 Rohkupfer in deinem Generator.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q029.name', 'de', 'quest.q029.name', 'Coal', 'Kohle');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q029.desc', 'de', 'quest.q029.desc', 'Find 16 coal in your generator.', 'Finde 16 Kohle in deinem Generator.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q030.name', 'de', 'quest.q030.name', 'Gold', 'Gold');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q030.desc', 'de', 'quest.q030.desc', 'Find a gold nugget in your generator.', 'Finde einen Goldklumpen in deinem Generator.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q031.name', 'de', 'quest.q031.name', 'Bronze Age', 'Bronzezeit');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q031.desc', 'de', 'quest.q031.desc', 'Bronzite, the first metal the Call taught the survivors. Your journey beyond the islet begins. Find your first Bronzite in your generator.', 'Bronzite, das erste Metall, das der Ruf die Überlebenden lehrte. Deine Reise über das Inselchen hinaus beginnt. Finde dein erstes Bronzite in deinem Generator.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q032.name', 'de', 'quest.q032.name', 'Mine 250', '250 abbauen');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q032.desc', 'de', 'quest.q032.desc', 'Break 250 cobblestone.', 'Baue 250 Bruchstein ab.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q033.name', 'de', 'quest.q033.name', 'Mine 500', '500 abbauen');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q033.desc', 'de', 'quest.q033.desc', 'Break 500 cobblestone.', 'Baue 500 Bruchstein ab.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q034.name', 'de', 'quest.q034.name', 'Smelter', 'Schmelzer');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q034.desc', 'de', 'quest.q034.desc', 'Craft a furnace.', 'Stelle einen Ofen her.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q035.name', 'de', 'quest.q035.name', 'Storage', 'Lagerung');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q035.desc', 'de', 'quest.q035.desc', 'Craft two chests.', 'Stelle zwei Truhen her.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q036.name', 'de', 'quest.q036.name', 'Iron Pickaxe', 'Eisenspitzhacke');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q036.desc', 'de', 'quest.q036.desc', 'Craft an iron pickaxe.', 'Stelle eine Eisenspitzhacke her.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q037.name', 'de', 'quest.q037.name', 'Visit the Market', 'Den Markt besuchen');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q037.desc', 'de', 'quest.q037.desc', 'Open the market with /market.', 'Öffne den Markt mit /market.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q038.name', 'de', 'quest.q038.name', 'First Sales', 'Erste Verkäufe');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q038.desc', 'de', 'quest.q038.desc', 'Earn 200 coins.', 'Verdiene 200 Münzen.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q039.name', 'de', 'quest.q039.name', 'Dune Plan', 'Dünenplan');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q039.desc', 'de', 'quest.q039.desc', 'Read the plans of the other generators with /guide.', 'Lies die Pläne der anderen Generatoren mit /guide.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q040.name', 'de', 'quest.q040.name', 'Sandstone', 'Sandstein');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q040.desc', 'de', 'quest.q040.desc', 'Craft 16 sandstone.', 'Stelle 16 Sandstein her.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q041.name', 'de', 'quest.q041.name', 'Dune Ring', 'Dünenring');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q041.desc', 'de', 'quest.q041.desc', 'Place 7 sandstone blocks around a second Fountain (a Spring Stone on the south side).', 'Platziere 7 Sandsteinblöcke rund um einen zweiten Brunnen (ein Quellstein auf der Südseite).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q042.name', 'de', 'quest.q042.name', 'Dune Generator', 'Dünengenerator');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q042.desc', 'de', 'quest.q042.desc', 'Complete the sandstone ring: a Dune generator makes sand, gravel and red sand.', 'Vervollständige den Sandsteinring: Ein Dünengenerator erzeugt Sand, Kies und Roten Sand.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q043.name', 'de', 'quest.q043.name', 'Sand', 'Sand');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q043.desc', 'de', 'quest.q043.desc', 'Break 64 sand.', 'Baue 64 Sand ab.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q044.name', 'de', 'quest.q044.name', 'Gravel', 'Kies');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q044.desc', 'de', 'quest.q044.desc', 'Break 64 gravel.', 'Baue 64 Kies ab.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q045.name', 'de', 'quest.q045.name', 'Red Sand', 'Roter Sand');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q045.desc', 'de', 'quest.q045.desc', 'Break 16 red sand.', 'Baue 16 Roten Sand ab.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q046.name', 'de', 'quest.q046.name', 'Glass', 'Glas');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q046.desc', 'de', 'quest.q046.desc', 'Smelt 8 glass: put sand in a furnace and take the glass out.', 'Schmelze 8 Glas: Lege Sand in einen Ofen und nimm das Glas heraus.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q047.name', 'de', 'quest.q047.name', 'Concrete', 'Beton');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q047.desc', 'de', 'quest.q047.desc', 'Craft 8 concrete powder.', 'Stelle 8 Trockenbeton her.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q048.name', 'de', 'quest.q048.name', 'More Glass', 'Mehr Glas');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q048.desc', 'de', 'quest.q048.desc', 'Smelt 16 more glass (stained glass counts too).', 'Schmelze 16 weiteres Glas (gefärbtes Glas zählt auch).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q049.name', 'de', 'quest.q049.name', 'Frost Ring', 'Frostring');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q049.desc', 'de', 'quest.q049.desc', 'Place 7 glass blocks around a third Fountain (a Spring Stone on the south side).', 'Platziere 7 Glasblöcke rund um einen dritten Brunnen (ein Quellstein auf der Südseite).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q050.name', 'de', 'quest.q050.name', 'Frost Generator', 'Frostgenerator');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q050.desc', 'de', 'quest.q050.desc', 'Complete the glass ring: a Frost generator makes snow blocks, packed ice and Frostium.', 'Vervollständige den Glasring: Ein Frostgenerator erzeugt Schneeblöcke, Packeis und Frostium.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q051.name', 'de', 'quest.q051.name', 'Snow', 'Schnee');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q051.desc', 'de', 'quest.q051.desc', 'Break 32 snow blocks.', 'Baue 32 Schneeblöcke ab.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q052.name', 'de', 'quest.q052.name', 'Ice', 'Eis');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q052.desc', 'de', 'quest.q052.desc', 'Break 16 packed ice.', 'Baue 16 Packeis ab.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q053.name', 'de', 'quest.q053.name', 'Frostium', 'Frostium');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q053.desc', 'de', 'quest.q053.desc', 'Find your first Frostium in the blocks of your Frost generator.', 'Finde dein erstes Frostium in den Blöcken deines Frostgenerators.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q054.name', 'de', 'quest.q054.name', 'Frostium Haul', 'Frostium-Ausbeute');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q054.desc', 'de', 'quest.q054.desc', 'Find 8 Frostium in the blocks of your Frost generator.', 'Finde 8 Frostium in den Blöcken deines Frostgenerators.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q055.name', 'de', 'quest.q055.name', 'Second Spring', 'Zweite Quelle');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q055.desc', 'de', 'quest.q055.desc', 'Place 2 more Spring Stones.', 'Platziere 2 weitere Quellsteine.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q056.name', 'de', 'quest.q056.name', 'More Fountains', 'Mehr Brunnen');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q056.desc', 'de', 'quest.q056.desc', 'Place 3 more Fountains.', 'Platziere 3 weitere Brunnen.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q057.name', 'de', 'quest.q057.name', 'The Forge', 'Die Schmiede');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q057.desc', 'de', 'quest.q057.desc', 'The Forge is the heart of every survivor camp: it turns raw memory into tools. Craft a Forge with a blast furnace, 4 iron ingots and 4 coal, then place it.', 'Die Schmiede ist das Herz jedes Überlebendenlagers: Sie verwandelt rohe Erinnerung in Werkzeuge. Stelle eine Schmiede aus einem Schmelzofen, 4 Eisenbarren und 4 Kohle her und platziere sie.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q058.name', 'de', 'quest.q058.name', 'Open the Forge', 'Die Schmiede öffnen');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q058.desc', 'de', 'quest.q058.desc', 'Open the Forge menu with /forge.', 'Öffne das Schmiedemenü mit /forge.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q059.name', 'de', 'quest.q059.name', 'First Forging', 'Erstes Schmieden');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q059.desc', 'de', 'quest.q059.desc', 'Collect a Bronze Core from the Forge (/forge).', 'Hol dir einen Bronzekern aus der Schmiede (/forge).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q060.name', 'de', 'quest.q060.name', 'Raise the Generator', 'Generator aufwerten');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q060.desc', 'de', 'quest.q060.desc', 'Reach generator tier II: forge a Bronze Core and right-click it on your island.', 'Erreiche Generatorstufe II: Schmiede einen Bronzekern und mach damit auf deiner Insel einen Rechtsklick.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q061.name', 'de', 'quest.q061.name', 'Tier II Mining', 'Abbau auf Stufe II');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q061.desc', 'de', 'quest.q061.desc', 'Break 500 more cobblestone.', 'Baue 500 weitere Bruchsteine ab.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q062.name', 'de', 'quest.q062.name', 'Bronzite Hoard', 'Bronzite-Schatz');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q062.desc', 'de', 'quest.q062.desc', 'Find 12 Bronzite in your generator.', 'Finde 12 Bronzite in deinem Generator.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q063.name', 'de', 'quest.q063.name', 'Diamond', 'Diamant');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q063.desc', 'de', 'quest.q063.desc', 'Find a diamond in your generator.', 'Finde einen Diamanten in deinem Generator.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q064.name', 'de', 'quest.q064.name', 'Ember Core', 'Glutkern');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q064.desc', 'de', 'quest.q064.desc', 'Collect an Ember Core from the Forge (/forge).', 'Hol dir einen Glutkern aus der Schmiede (/forge).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q065.name', 'de', 'quest.q065.name', 'Tier III', 'Stufe III');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q065.desc', 'de', 'quest.q065.desc', 'Reach generator tier III: forge an Ember Core and right-click it on your island.', 'Erreiche Generatorstufe III: Schmiede einen Glutkern und mach damit auf deiner Insel einen Rechtsklick.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q066.name', 'de', 'quest.q066.name', 'Ancient Debris', 'Antiker Schrott');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q066.desc', 'de', 'quest.q066.desc', 'Find ancient debris in your generator.', 'Finde Antiken Schrott in deinem Generator.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q067.name', 'de', 'quest.q067.name', 'Mine 2,000', '2.000 abbauen');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q067.desc', 'de', 'quest.q067.desc', 'Break 2,000 cobblestone.', 'Baue 2.000 Bruchstein ab.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q068.name', 'de', 'quest.q068.name', 'Void Lens', 'Leerenlinse');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q068.desc', 'de', 'quest.q068.desc', 'Collect a Void Lens from the Forge (/forge).', 'Hol dir eine Leerenlinse aus der Schmiede (/forge).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q069.name', 'de', 'quest.q069.name', 'The Void Lens', 'Die Leerenlinse');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q069.desc', 'de', 'quest.q069.desc', 'Through the lens you glimpse the gap the Devourer tore in the sky: the Rift. Reach generator tier IV: right-click the Void Lens on your island. It also opens your End (/island end).', 'Durch die Linse erblickst du die Lücke, die der Verschlinger in den Himmel gerissen hat: den Riss. Erreiche Generatorstufe IV: Mach mit der Leerenlinse auf deiner Insel einen Rechtsklick. Sie öffnet auch dein End (/island end).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q070.name', 'de', 'quest.q070.name', 'Voidglass', 'Voidglass');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q070.desc', 'de', 'quest.q070.desc', 'Find a Voidglass in your generator.', 'Finde ein Voidglass in deinem Generator.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q071.name', 'de', 'quest.q071.name', 'Starcore', 'Starcore');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q071.desc', 'de', 'quest.q071.desc', 'Find a Starcore Shard in your generator.', 'Finde einen Starcore-Splitter in deinem Generator.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q072.name', 'de', 'quest.q072.name', 'Mine 5,000', '5.000 abbauen');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q072.desc', 'de', 'quest.q072.desc', 'Break 5,000 cobblestone.', 'Baue 5.000 Bruchstein ab.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.hub_gate.name', 'de', 'quest.hub_gate.name', 'The Island Gate', 'Das Inseltor');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.hub_gate.desc', 'de', 'quest.hub_gate.desc', 'Bronze on your back, you feel the fragment loosen. Beyond the gate there are other survivors. Travel to the Hub with /hub (and use /island to come back).', 'Mit Bronze auf dem Rücken spürst du, wie sich das Fragment lockert. Jenseits des Tors warten andere Überlebende. Reise mit /hub zum Hub (und kehre mit /island zurück).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.hub_guard.name', 'de', 'quest.hub_guard.name', 'The Guard', 'Die Wache');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.hub_guard.desc', 'de', 'quest.hub_guard.desc', 'Click the Guard on the Hub plaza and listen.', 'Klicke auf die Wache auf dem Hub-Platz und hör ihr zu.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.hub_archivist.name', 'de', 'quest.hub_archivist.name', 'The Archivist', 'Die Archivarin');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.hub_archivist.desc', 'de', 'quest.hub_archivist.desc', 'The Archivist has kept a key cut from a shard that still remembers the sky. Click the Archivist on the Hub plaza: she keeps the key to the Rift.', 'Die Archivarin hat einen Schlüssel aufbewahrt, geschnitten aus einem Splitter, der sich noch an den Himmel erinnert. Klicke auf die Archivarin auf dem Hub-Platz: Sie verwahrt den Schlüssel zum Riss.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.hub_merchant.name', 'de', 'quest.hub_merchant.name', 'The Merchant', 'Der Händler');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.hub_merchant.desc', 'de', 'quest.hub_merchant.desc', 'Click the Merchant on the Hub plaza to learn how the market works.', 'Klicke auf den Händler auf dem Hub-Platz, um zu erfahren, wie der Markt funktioniert.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.hub_market_lesson.name', 'de', 'quest.hub_market_lesson.name', 'Market Lesson', 'Marktlektion');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.hub_market_lesson.desc', 'de', 'quest.hub_market_lesson.desc', 'Earn 300 coins.', 'Verdiene 300 Münzen.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.rift_enter.name', 'de', 'quest.rift_enter.name', 'Enter the Rift', 'Den Riss betreten');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.rift_enter.desc', 'de', 'quest.rift_enter.desc', 'Carry your Echo Key to the Rift arch, west of the Hub plaza, and click the Rift Gatekeeper.', 'Trage deinen Echoschlüssel zum Rissbogen westlich des Hub-Platzes und klicke auf den Torhüter des Risses.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.echo_defeat.name', 'de', 'quest.echo_defeat.name', 'Defeat the Echo of the Rift', 'Besiege das Echo des Risses');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.echo_defeat.desc', 'de', 'quest.echo_defeat.desc', 'The first Echo of the Devourer screams in the sky. End it, and the Eight Realms can be reached. Right-click the Echo Key on the Rift altar, then defeat the Echo of the Rift. It drops the Wing Core that grants your Wings and lights the road to the Quai des Huit.', 'Das erste Echo des Verschlingers schreit am Himmel. Beende es, und die Acht Reiche werden erreichbar. Mach mit dem Echoschlüssel einen Rechtsklick auf den Rissaltar und besiege dann das Echo des Risses. Es lässt den Flügelkern fallen, der dir deine Flügel schenkt und den Weg zum Quai des Huit erhellt.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q073.name', 'de', 'quest.q073.name', 'Nether Plan', 'Netherplan');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q073.desc', 'de', 'quest.q073.desc', 'Read the Nether plan with /guide.', 'Lies den Netherplan mit /guide.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q074.name', 'de', 'quest.q074.name', 'Flint and Steel', 'Feuerzeug');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q074.desc', 'de', 'quest.q074.desc', 'Craft flint and steel.', 'Stelle ein Feuerzeug her.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q075.name', 'de', 'quest.q075.name', 'Light a Portal', 'Ein Portal entzünden');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q075.desc', 'de', 'quest.q075.desc', 'Place 10 obsidian.', 'Platziere 10 Obsidian.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q076.name', 'de', 'quest.q076.name', 'Enter the Nether', 'Ab in den Nether');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q076.desc', 'de', 'quest.q076.desc', 'Enter your Nether.', 'Betritt deinen Nether.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q077.name', 'de', 'quest.q077.name', 'Netherrack', 'Netherrack');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q077.desc', 'de', 'quest.q077.desc', 'Break 64 netherrack.', 'Baue 64 Netherrack ab.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q078.name', 'de', 'quest.q078.name', 'Nether Bricks', 'Netherziegel');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q078.desc', 'de', 'quest.q078.desc', 'Craft 16 nether bricks.', 'Stelle 16 Netherziegel her.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q079.name', 'de', 'quest.q079.name', 'Magma Block', 'Magmablock');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q079.desc', 'de', 'quest.q079.desc', 'Craft a magma block from 4 netherrack and 1 coal.', 'Stelle einen Magmablock aus 4 Netherrack und 1 Kohle her.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q080.name', 'de', 'quest.q080.name', 'Ember Ring', 'Glutring');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q080.desc', 'de', 'quest.q080.desc', 'Place 7 nether bricks around a Fountain (a magma block on the south side).', 'Platziere 7 Netherziegel rund um einen Brunnen (ein Magmablock auf der Südseite).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q081.name', 'de', 'quest.q081.name', 'Ember Generator', 'Glutgenerator');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q081.desc', 'de', 'quest.q081.desc', 'Complete the ring with a magma block on the south side: an Ember generator makes netherrack and soul sand.', 'Schließe den Ring mit einem Magmablock auf der Südseite: Ein Glutgenerator erzeugt Netherrack und Seelensand.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q082.name', 'de', 'quest.q082.name', 'Quartz Block', 'Quarzblock');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q082.desc', 'de', 'quest.q082.desc', 'Craft a quartz block from 4 nether quartz (from the Ember generator or the market).', 'Stelle einen Quarzblock aus 4 Netherquarz her (aus dem Glutgenerator oder vom Markt).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q083.name', 'de', 'quest.q083.name', 'Soul Sand', 'Seelensand');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.q083.desc', 'de', 'quest.q083.desc', 'Break 32 soul sand.', 'Baue 32 Seelensand ab.');
