INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.grove_01.name', 'de', 'quest.grove_01.name', 'Through the Green Gate', 'Durch das grüne Tor');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.grove_01.desc', 'de', 'quest.grove_01.desc', 'Beyond the second Gate the air is thick with light. The Grove remembers how to grow. Light the Sky Gate of the Whispering Grove (defeat the Lava Colossus) and step through it at the Quai des Huit (/quai).', 'Hinter dem zweiten Tor ist die Luft dick vor Licht. Der Hain erinnert sich, wie man wächst. Entzünde das Himmelstor des Flüsternden Hains (besiege den Lavakoloss) und tritt am Quai des Huit (/quai) hindurch.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.grove_02.name', 'de', 'quest.grove_02.name', 'Mossy Footing', 'Moosiger Untergrund');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.grove_02.desc', 'de', 'quest.grove_02.desc', 'Break 32 moss blocks.', 'Baue 32 Moosblöcke ab.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.grove_03.name', 'de', 'quest.grove_03.name', 'First Grove Harvest', 'Erste Hainernte');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.grove_03.desc', 'de', 'quest.grove_03.desc', 'Break 16 fully grown crops.', 'Baue 16 ausgewachsene Feldfrüchte ab.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.grove_04.name', 'de', 'quest.grove_04.name', 'Breathe the Spores', 'Atme die Sporen');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.grove_04.desc', 'de', 'quest.grove_04.desc', 'Harvest grown crops in the Grove until you earn the Respiration affinity (40 harvests): the spore haze no longer touches you.', 'Ernte ausgewachsene Feldfrüchte im Hain, bis du die Affinität Atmung erhältst (40 Ernten): Der Sporendunst kann dir nichts mehr anhaben.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.grove_05.name', 'de', 'quest.grove_05.name', 'Planting the Roots', 'Wurzeln pflanzen');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.grove_05.desc', 'de', 'quest.grove_05.desc', 'Plant 32 saplings.', 'Pflanze 32 Setzlinge.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.grove_06.name', 'de', 'quest.grove_06.name', 'Heartwood', 'Kernholz');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.grove_06.desc', 'de', 'quest.grove_06.desc', 'Break 64 mangrove logs, the living wood of the Grove.', 'Baue 64 Mangrovenstämme ab, das lebendige Holz des Hains.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.grove_07.name', 'de', 'quest.grove_07.name', 'Tame the Green', 'Zähme das Grün');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.grove_07.desc', 'de', 'quest.grove_07.desc', 'Craft a composter.', 'Stelle einen Komposter her.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.grove_08.name', 'de', 'quest.grove_08.name', 'Let It Grow', 'Lass es wachsen');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.grove_08.desc', 'de', 'quest.grove_08.desc', 'Keep harvesting in the Grove until you earn the Growth affinity (200 harvests): bone meal grows a crop one more stage, anywhere.', 'Ernte weiter im Hain, bis du die Affinität Wachstum erhältst (200 Ernten): Knochenmehl lässt eine Pflanze überall eine Stufe weiterwachsen.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.grove_09.name', 'de', 'quest.grove_09.name', 'Wake the Mycelial Queen', 'Weck die Myzelkönigin');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.grove_09.desc', 'de', 'quest.grove_09.desc', 'Defeat the Mycelial Queen, Guardian of the Grove.', 'Besiege die Myzelkönigin, die Wächterin des Hains.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.heights_01.name', 'de', 'quest.heights_01.name', 'Through the Frozen Gate', 'Durch das gefrorene Tor');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.heights_01.desc', 'de', 'quest.heights_01.desc', 'Beyond the third Gate nothing moves unless you make it. The Heights keep time in their ice. Light the Sky Gate of the Frozen Heights (defeat the Mycelial Queen) and step through it at the Quai des Huit (/quai).', 'Hinter dem dritten Tor bewegt sich nichts, wenn du es nicht bewegst. Die Höhen bewahren die Zeit in ihrem Eis. Entzünde das Himmelstor der Gefrorenen Höhen (besiege die Myzelkönigin) und tritt am Quai des Huit (/quai) hindurch.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.heights_02.name', 'de', 'quest.heights_02.name', 'Cutting Ice', 'Eis schneiden');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.heights_02.desc', 'de', 'quest.heights_02.desc', 'Break 32 packed ice.', 'Baue 32 Packeis ab.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.heights_03.name', 'de', 'quest.heights_03.name', 'Blue Cut', 'Blauer Schnitt');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.heights_03.desc', 'de', 'quest.heights_03.desc', 'Break 16 blue ice.', 'Baue 16 Blaueis ab.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.heights_04.name', 'de', 'quest.heights_04.name', 'Warmth', 'Wärme');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.heights_04.desc', 'de', 'quest.heights_04.desc', 'Cut ice in the Heights until you earn the Warmth affinity (40 blocks): the cold no longer bites you.', 'Schneide Eis in den Höhen, bis du die Affinität Wärme erhältst (40 Blöcke): Die Kälte beißt dich nicht mehr.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.heights_05.name', 'de', 'quest.heights_05.name', 'Crystal Spires', 'Kristalltürme');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.heights_05.desc', 'de', 'quest.heights_05.desc', 'Break 8 amethyst clusters, the crystals of the Heights.', 'Baue 8 Amethysthaufen ab, die Kristalle der Höhen.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.heights_06.name', 'de', 'quest.heights_06.name', 'Cold Storage', 'Kühllager');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.heights_06.desc', 'de', 'quest.heights_06.desc', 'Craft a blast furnace.', 'Stelle einen Schmelzofen her.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.heights_07.name', 'de', 'quest.heights_07.name', 'Stray Hunt', 'Eiswanderer-Jagd');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.heights_07.desc', 'de', 'quest.heights_07.desc', 'Defeat 20 strays.', 'Besiege 20 Eiswanderer.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.heights_08.name', 'de', 'quest.heights_08.name', 'Stasis', 'Stase');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.heights_08.desc', 'de', 'quest.heights_08.desc', 'Keep cutting ice in the Heights until you earn the Stasis affinity (200 blocks): sneak in the air to slow your fall, anywhere in the Heights.', 'Schneide weiter Eis in den Höhen, bis du die Affinität Stase erhältst (200 Blöcke): Schleiche in der Luft, um deinen Fall zu bremsen, überall in den Höhen.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.heights_09.name', 'de', 'quest.heights_09.name', 'Wake the Boreal Watcher', 'Weck den Boreal-Wächter');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.heights_09.desc', 'de', 'quest.heights_09.desc', 'Defeat the Boreal Watcher, Guardian of the Heights.', 'Besiege den Boreal-Wächter, den Wächter der Höhen.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.marsh_01.name', 'de', 'quest.marsh_01.name', 'Through the Brown Gate', 'Durch das braune Tor');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.marsh_01.desc', 'de', 'quest.marsh_01.desc', 'The fifth Gate smells of wet earth and old meals. Nothing here is ever really gone. Light the Sky Gate of the Putrid Marshes (defeat the Mycelial Queen) and step through it at the Quai des Huit (/quai).', 'Das fünfte Tor riecht nach nasser Erde und alten Mahlzeiten. Nichts ist hier je wirklich verschwunden. Entzünde das Himmelstor der Fauligen Sümpfe (besiege die Myzelkönigin) und tritt am Quai des Huit (/quai) hindurch.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.marsh_02.name', 'de', 'quest.marsh_02.name', 'Muddy Roots', 'Schlammige Wurzeln');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.marsh_02.desc', 'de', 'quest.marsh_02.desc', 'Break 32 muddy mangrove roots, where Rot Resin oozes.', 'Baue 32 schlammige Mangrovenwurzeln ab, aus denen Fäulnisharz sickert.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.marsh_03.name', 'de', 'quest.marsh_03.name', 'Feed the Vat', 'Füttere den Bottich');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.marsh_03.desc', 'de', 'quest.marsh_03.desc', 'Right-click a Rot Vat with expired items (rotten flesh, spider eyes, bones...) to salvage them.', 'Mach mit verdorbenen Gegenständen (verrottetes Fleisch, Spinnenaugen, Knochen ...) einen Rechtsklick auf einen Fäulnisbottich, um sie zu verwerten.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.marsh_04.name', 'de', 'quest.marsh_04.name', 'Filtered Air', 'Gefilterte Luft');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.marsh_04.desc', 'de', 'quest.marsh_04.desc', 'Salvage until you earn the Filtered affinity (40 points): the miasma no longer weakens you.', 'Verwerte, bis du die Affinität Gefiltert erhältst (40 Punkte): Das Miasma schwächt dich nicht mehr.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.marsh_05.name', 'de', 'quest.marsh_05.name', 'Slime Heaps', 'Schleimhaufen');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.marsh_05.desc', 'de', 'quest.marsh_05.desc', 'Break 16 slime blocks from the Landfill and the Weeping Mangrove.', 'Baue 16 Schleimblöcke aus der Müllkippe und der Weinenden Mangrove ab.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.marsh_06.name', 'de', 'quest.marsh_06.name', 'Reclaimer', 'Wiederverwerter');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.marsh_06.desc', 'de', 'quest.marsh_06.desc', 'Keep salvaging until you earn the Reclaimer affinity (200 points): a Vat needs fewer items for each Rot Resin roll.', 'Verwerte weiter, bis du die Affinität Wiederverwerter erhältst (200 Punkte): Ein Bottich braucht für jeden Fäulnisharz-Wurf weniger Gegenstände.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.marsh_07.name', 'de', 'quest.marsh_07.name', 'Digest the Digester', 'Verdau den Verdauer');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.marsh_07.desc', 'de', 'quest.marsh_07.desc', 'Defeat the Mire Abomination, Guardian of the Marshes.', 'Besiege das Sumpfscheusal, den Wächter der Sümpfe.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.citadel_01.name', 'de', 'quest.citadel_01.name', 'Through the Golden Gate', 'Durch das goldene Tor');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.citadel_01.desc', 'de', 'quest.citadel_01.desc', 'Beyond the fourth Gate the hours do not agree with each other. The Citadel counts them all. Light the Sky Gate of the Citadel of Golden Sands (defeat the Mycelial Queen) and step through it at the Quai des Huit (/quai).', 'Hinter dem vierten Tor sind sich die Stunden uneins. Die Zitadelle zählt sie alle. Entzünde das Himmelstor der Zitadelle der Goldenen Sande (besiege die Myzelkönigin) und tritt am Quai des Huit (/quai) hindurch.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.citadel_02.name', 'de', 'quest.citadel_02.name', 'Dunes of the Citadel', 'Dünen der Zitadelle');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.citadel_02.desc', 'de', 'quest.citadel_02.desc', 'Break 64 sandstone blocks.', 'Baue 64 Sandsteinblöcke ab.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.citadel_03.name', 'de', 'quest.citadel_03.name', 'Time Surges', 'Die Zeit rast');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.citadel_03.desc', 'de', 'quest.citadel_03.desc', 'Be in the Citadel when the Time Tide surges: you move faster, and Chrono Modules run fast.', 'Sei in der Zitadelle, wenn die Zeitflut anschwillt: Du bewegst dich schneller und Chronomodule laufen schneller.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.citadel_04.name', 'de', 'quest.citadel_04.name', 'Time Stalls', 'Die Zeit stockt');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.citadel_04.desc', 'de', 'quest.citadel_04.desc', 'Be in the Citadel when the Time Tide stalls: you move slower, and Chrono Modules bank the lost cycles.', 'Sei in der Zitadelle, wenn die Zeitflut stockt: Du bewegst dich langsamer und Chronomodule speichern die verlorenen Zyklen.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.citadel_05.name', 'de', 'quest.citadel_05.name', 'Gold of the Sands', 'Gold der Sande');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.citadel_05.desc', 'de', 'quest.citadel_05.desc', 'Collect 16 gold ingots to forge the Chrono Module and the Sandglass.', 'Sammle 16 Goldbarren, um das Chronomodul und die Sanduhr zu schmieden.');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.citadel_06.name', 'de', 'quest.citadel_06.name', 'Turn the Sandglass', 'Dreh die Sanduhr');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.citadel_06.desc', 'de', 'quest.citadel_06.desc', 'Collect a Sandglass from the Forge (/forge).', 'Hol dir eine Sanduhr aus der Schmiede (/forge).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.citadel_07.name', 'de', 'quest.citadel_07.name', 'A Module That Remembers', 'Ein Modul mit Gedächtnis');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.citadel_07.desc', 'de', 'quest.citadel_07.desc', 'Collect a Chrono Module from the Forge (/forge).', 'Hol dir ein Chronomodul aus der Schmiede (/forge).');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.citadel_08.name', 'de', 'quest.citadel_08.name', 'Wake the Temporal Pharaoh', 'Weck den Zeitpharao');
INSERT INTO i18n_text (id, locale, key, source, text) VALUES ('de:quest.citadel_08.desc', 'de', 'quest.citadel_08.desc', 'Defeat the Temporal Pharaoh, Guardian of the Citadel.', 'Besiege den Zeitpharao, den Wächter der Zitadelle.');
